import sys

from src.parser import parse_enabled


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if len(args) != 1:
        return 2
    if parse_enabled(args[0]):
        return 0
    return 1


if __name__ == "__main__":
    sys.exit(main())
